/bin/zsh -lc "python3 -c 'import csv, math, collections; f=[]
for fn in [\"processed/forces.csv\",\"processed/forces_b3.csv\"]:
 f+=list(csv.DictReader(open(fn)))
logs={int(x[\"run_id\"]):x for x in csv.DictReader(open(\"data/run_log.csv\"))}; groups=collections.defaultdict(list)
for a in f:
 r=int(a[\"run\"]); x=logs[r]; d=float(x[\"diameter_mm\"])/1000; v=float(x[\"speed_m_s\"]); cd=float(a[\"F_mean\"])/(.5*998*v*v*d*.6); re=v*d/1.004e-6; groups[x[\"cylinder\"]].append((r,re,cd))
for k,vals in groups.items():
 cds=[x[2] for x in vals]; print(k,\"n\",len(vals),\"Re\",min(x[1] for x in vals),max(x[1] for x in vals),\"Cd mean\",sum(cds)/len(cds),\"range\",min(cds),max(cds)); print([(a,round(c,3)) for a,b,c in vals])'"

